package com.example.helpdesk.web;
import com.example.helpdesk.model.*; import com.example.helpdesk.repo.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class RegistrationController { private final UserRepository users; private final PasswordEncoder encoder; public RegistrationController(UserRepository u,PasswordEncoder e){users=u;encoder=e;} @GetMapping("/register") String register(Model m){m.addAttribute("user",new User());return "register";} @PostMapping("/register") String create(@RequestParam String username,@RequestParam String fullName,@RequestParam String password,@RequestParam String confirmPassword,Model m){String clean=username==null?"":username.trim();if(clean.length()<3||fullName==null||fullName.trim().isBlank()){m.addAttribute("error","Please provide a username with at least 3 characters and your full name.");return "register";}if(password==null||password.length()<8){m.addAttribute("error","Password must be at least 8 characters.");return "register";}if(!password.equals(confirmPassword)){m.addAttribute("error","Passwords do not match.");return "register";}if(users.findByUsername(clean).isPresent()){m.addAttribute("error","That username is already in use.");return "register";}users.save(new User(clean,encoder.encode(password),fullName.trim(),Role.EMPLOYEE));return "redirect:/login?registered";} }
